# -*- coding: utf-8 -*-
import json, sys
P={}; R={}
def md(i,pre,t): P[i]=(pre,t)
def de(i,pre): P[i]=(pre,None)
md(70,"Đề cương dùng các khái niệm","Đề cương dùng các khái niệm sau với nghĩa cố định. Năng lực cạnh tranh của trung tâm tài chính là khả năng giữ và thu hút các tổ chức tài chính và cung cấp dịch vụ đáp ứng nhu cầu trong nước và quốc tế (Yao, 2012), đo bằng điểm GFCI. Chất lượng thị trường vốn gồm ba chiều: thanh khoản, hiệu quả thông tin và minh bạch công bố. Khả năng đầu tư của một rổ cổ phiếu là lợi suất tương đương chắc chắn sau chi phí giao dịch mà nhà đầu tư đa dạng hóa đạt được với rổ đó, khác với nghĩa giới hạn sở hữu của nhà đầu tư nước ngoài (Bae và cộng sự, 2004).")
md(73,"Lộ trình hợp nhất đã bị lùi","Lộ trình hợp nhất đã bị lùi hai lần. Hạn chuyển cổ phiếu niêm yết từ HNX sang HOSE là năm 2023 theo Thông tư số 57/2021/TT-BTC, hết năm 2025 theo Thông tư số 69/2023/TT-BTC (Bộ Tài chính, 2023) và hết ngày 31/12/2026 theo Thông tư số 139/2025/TT-BTC (Bộ Tài chính, 2025); HNX ngừng nhận hồ sơ niêm yết cổ phiếu mới từ ngày 01/7/2025. Theo thông báo ngày 30/9/2026 của Sở Giao dịch Chứng khoán Việt Nam (VNX), cổ phiếu niêm yết tại HNX giao dịch phiên cuối ngày 23/12/2026, tạm ngừng hai ngày 24 và 25/12/2026, và giao dịch tại HOSE từ ngày 28/12/2026 (Sở Giao dịch Chứng khoán Việt Nam, 2026).")
md(74,"Hạn chuyển cổ phiếu UPCoM","Hạn chuyển cổ phiếu UPCoM sang HOSE cũng là hết ngày 31/12/2026, do Thông tư số 69/2023/TT-BTC đặt và không bị Thông tư số 139/2025/TT-BTC sửa (Bộ Tài chính, 2023). Tuy vậy, thông báo của VNX chỉ áp dụng cho cổ phiếu niêm yết, báo chí cho biết cổ phiếu UPCoM không thuộc diện chuyển trong đợt này (Báo Đầu tư Chứng khoán, 2026), và chưa có văn bản công bố lịch chuyển cổ phiếu UPCoM [CẦN XÁC MINH kế hoạch chuyển cổ phiếu đăng ký giao dịch theo khoản 4 Điều 4 Thông tư số 57/2021/TT-BTC].")
md(75,"Lý thuyết về trung tâm tài chính","Lý thuyết về trung tâm tài chính giải thích vì sao hoạt động tài chính dồn về một vài thành phố: quy mô giao dịch và thông tin tạo lợi thế tích tụ (Kindleberger, 1974; Gehrig, 2000). Khi một quốc gia có nhiều trung tâm, các trung tâm phân vai. Ở Trung Quốc, Thượng Hải là trung tâm thương mại, Bắc Kinh là trung tâm chính trị và quản lý, Hồng Kông là trung tâm hải ngoại (Lai, 2012); Bắc Kinh là một trung tâm tài chính lớn dù không có sở giao dịch chứng khoán tầm quốc gia trong phần lớn quá trình phát triển (Naeem, 2023). Với Hà Nội, câu hỏi sau hợp nhất là nên chuyên môn hóa vào những thị trường nào (Yao, 2012).")
md(83,"Mục tiêu nghiên cứu.","**Mục tiêu nghiên cứu.** Mục tiêu tổng quát là đo khoảng cách chất lượng thị trường giữa hai sàn trước hợp nhất và lượng hóa tác động của việc chuyển sàn năm 2026 lên thanh khoản và khả năng đầu tư của các cổ phiếu chuyển sàn, làm căn cứ cho định hướng chuyên môn hóa của thị trường vốn Hà Nội.")
md(84,"Đề tài có bốn mục tiêu cụ thể","Bốn mục tiêu cụ thể là: (i) ước lượng liên hệ giữa mức phát triển thị trường cổ phiếu và điểm GFCI trên dữ liệu bảng quốc tế; (ii) xây dựng Chỉ số chất lượng thị trường vốn theo tháng cho sàn niêm yết HNX, UPCoM và HOSE; (iii) ước lượng tác động của việc chuyển sàn lên thanh khoản và khả năng đầu tư, kể cả mức thay đổi của tác động theo mức chịu cú sốc biên độ, bước giá, chỉ số và theo trụ sở doanh nghiệp; (iv) tổng hợp định tính các kết quả thành định hướng chuyên môn hóa và hạ tầng dữ liệu cho thị trường vốn Hà Nội. Trong bốn giả thuyết ở mục 4.3.2, H3 là kiểm định trọng tâm; H1 cung cấp bối cảnh quốc tế, H2 cung cấp thước đo nền trước sự kiện, và H4 quy đổi tác động sang khả năng đầu tư.")
de(85,"Trong bốn giả thuyết")
md(86,"Đóng góp dự kiến.","**Đóng góp dự kiến.** So với Yao (2012), Eichengreen và Shah (2020) và Naeem (2023), đề tài đưa riêng mức phát triển thị trường cổ phiếu vào mô hình điểm GFCI. So với Nielsson (2009) và Hisada (2018), đề tài nghiên cứu hợp nhất hai sàn trong một quốc gia mới nổi, dùng suy luận phù hợp với một sự kiện duy nhất và đo thêm tác động lên khả năng đầu tư. So với các công trình về Việt Nam (Vo & Phan, 2017; Goutte và cộng sự, 2025; Nguyễn & Nguyễn, 2026a), đề tài xây dựng chỉ số so sánh HNX với HOSE và cung cấp bằng chứng đầu tiên, trong phạm vi tìm kiếm của thí sinh, về đợt hợp nhất năm 2026.")
md(87,"Về sản phẩm,","Về sản phẩm, Chỉ số chất lượng thị trường vốn có thể là một cấu phần của sản phẩm “Hệ thống dữ liệu tài chính đô thị” mà bài toán số 19 nêu, còn báo cáo định hướng chuyên môn hóa là một đầu vào phân tích cho sản phẩm “Trung tâm tài chính quốc tế tại Hà Nội”. Đề tài không thiết kế sản phẩm thứ hai, và Nghị quyết số 222/2025/QH15 hiện chỉ đặt trung tâm tài chính quốc tế tại Thành phố Hồ Chí Minh và Đà Nẵng. Hai chỉ số và tệp đăng ký trước là sản phẩm có được dù kết quả kiểm định ra sao.")
md(91,"(3) Ước lượng tác động","(3) Ước lượng tác động của việc chuyển sàn lên thanh khoản với 24 tháng dữ liệu sau sự kiện, kèm hiệu ứng nhỏ nhất phát hiện được và khoảng tin cậy, theo đúng tệp đăng ký.")
md(94,"(6) Báo cáo định hướng","(6) Báo cáo định hướng chuyên môn hóa cho các thị trường do HNX tiếp tục vận hành, gửi Sở Khoa học và Công nghệ Hà Nội trong năm thứ tư, kèm văn bản xác nhận nhu cầu sử dụng kết quả của ít nhất một đơn vị, ưu tiên HNX.")
md(96,"(A) Trung tâm tài chính","*(A) Trung tâm tài chính: tích tụ, cạnh tranh và phân vai.* Kindleberger (1974) và Gehrig (2000) giải thích sự tập trung của hoạt động tài chính bằng lợi thế quy mô và thông tin. Yao (2012) xác định các yếu tố quyết định sức hấp dẫn của trung tâm đối với ngành quỹ đầu tư qua trường hợp Luxembourg. Moosa và cộng sự (2016) kiểm tra độ vững của các yếu tố quyết định vị thế trung tâm, còn Eichengreen và Shah (2020) xếp các yếu tố thành năm nhóm, trong đó có nhóm phát triển tài chính và vốn hóa thị trường.")
md(97,"Naeem (2023) dùng dữ liệu","Naeem (2023) hồi quy thứ hạng GFCI của 196 trung tâm giai đoạn 2007–2020 theo 17 yếu tố chọn bằng phương pháp cây quyết định; các yếu tố này không gồm chỉ báo thị trường cổ phiếu. Cetorelli và Peristiani (2013) đo vị thế trung tâm qua mạng lưới niêm yết quốc tế của sàn. Ở Trung Quốc, Lai (2012) và Wang và cộng sự (2007) mô tả sự phân vai giữa Bắc Kinh, Thượng Hải và Hồng Kông, Chen và Chen (2015) nhấn mạnh vai trò dẫn dắt của nhà nước, còn Elliott (2011) rút ra rằng không có công thức chung để xây dựng một trung tâm toàn cầu.")
md(98,"(B) Chất lượng thị trường vốn","*(B) Chất lượng thị trường vốn.* Các chỉ báo thanh khoản tính từ dữ liệu ngày gồm độ phi thanh khoản (Amihud, 2002), tần suất ngày có lợi suất bằng 0 (Lesmond và cộng sự, 1999), được Bekaert và cộng sự (2007) dùng làm thước đo chính ở thị trường mới nổi, và chênh lệch mua-bán ước lượng từ giá cao nhất và thấp nhất (Corwin & Schultz, 2012); Lesmond (2005) và Fong và cộng sự (2017) đánh giá chỉ báo nào đo thanh khoản tốt nhất. Hiệu quả thông tin được đo bằng tỷ số phương sai (Lo & MacKinlay, 1988) và độ trễ giá (Hou & Moskowitz, 2005), dù các thước đo này có thể cho kết luận sai khi môi trường thông tin khác nhau (Griffin và cộng sự, 2010).\n\nLang và cộng sự (2012) nối minh bạch với thanh khoản, còn Čihák và cộng sự (2012) xây dựng Cơ sở dữ liệu Phát triển Tài chính Toàn cầu với các chỉ báo vòng quay và vốn hóa. Các thước đo này chưa được quy đổi thành tổn thất của nhà đầu tư đa dạng hóa.")
de(99,"Về hiệu quả thông tin")
md(100,"(C) Cấu trúc sàn","*(C) Cấu trúc sàn, đổi sàn và hợp nhất sàn.* Huang và Stoll (1996) so sánh chi phí giao dịch của các cặp cổ phiếu tương đồng trên hai sàn trong cùng một quốc gia, và Christie và Huang (1994) đo thanh khoản của cùng một cổ phiếu khi doanh nghiệp đổi sàn. Khi Sở Giao dịch Chứng khoán Tel Aviv chuyển cổ phiếu sang cơ chế có thêm phiên giao dịch liên tục, lợi suất bất thường tích lũy điều chỉnh theo thị trường đạt khoảng 5,5% trong giai đoạn từ năm ngày trước công bố đến 30 ngày sau khi cổ phiếu giao dịch theo cơ chế mới, và thanh khoản tăng cùng giá (Amihud và cộng sự, 1997).")
md(101,"Nielsson (2009) thấy","Việc hình thành Euronext làm thanh khoản tăng ở doanh nghiệp lớn và doanh nghiệp có doanh thu nước ngoài, nhưng không tăng ở doanh nghiệp nhỏ (Nielsson, 2009). Sau khi thị trường cổ phiếu của Osaka được hợp nhất vào Tokyo ngày 16/7/2013, thanh khoản của các cổ phiếu sẵn có trên Sở Giao dịch Chứng khoán Tokyo, đo bằng vòng quay và độ phi thanh khoản Amihud, tăng trong ngắn hạn rồi giảm sau một năm, với hiệu ứng tâm lý mạnh hơn ở cổ phiếu nhỏ (Hisada, 2018). Arnold và cộng sự (1999, dẫn theo Hisada, 2018) cũng thấy hợp nhất sàn làm thanh khoản tăng, và Wójcik (2007) phân tích quan hệ hai chiều giữa sàn chứng khoán và trung tâm tài chính. Bằng chứng ở thị trường mới nổi còn ít và chưa đo khả năng đầu tư.")
md(102,"(D) Đa dạng hóa danh mục","*(D) Đa dạng hóa danh mục khi tham số được ước lượng.* Tối ưu hóa trung bình-phương sai (Markowitz, 1952) dồn trọng số vào tài sản có sai số ước lượng lớn (Michaud, 1989), và hiệu quả ngoài mẫu giảm khi dùng ước lượng mẫu thay tham số tổng thể (Kan & Zhou, 2007). Các cách khắc phục gồm co rút ma trận hiệp phương sai (Ledoit & Wolf, 2004), mô hình Black-Litterman (Black & Litterman, 1992), cách tiếp cận mà Bessler và cộng sự (2017) thấy cho hiệu quả ngoài mẫu tốt trên dữ liệu đa tài sản, và danh mục vững chắc với nhiều niềm tin tiên nghiệm (Garlappi và cộng sự, 2007).\n\nDù vậy, DeMiguel và cộng sự (2009) không thấy mô hình nào vượt quy tắc 1/N một cách nhất quán, và Pflug và cộng sự (2012) chứng minh 1/N xấp xỉ tối ưu khi mức mơ hồ về mô hình cao. Ledoit và Wolf (2008) kiểm định chênh lệch tỷ số Sharpe giữa hai danh mục. Đề tài dùng nhóm công cụ này để đo khả năng đầu tư của một sàn, không để chọn mô hình tốt nhất.")
de(103,"DeMiguel và cộng sự (2009) không thấy")
md(104,"(E) Nghiên cứu về Việt Nam","*(E) Nghiên cứu về Việt Nam.* Vo và Phan (2017) tìm thấy hành vi bầy đàn trên 299 công ty niêm yết tại HOSE giai đoạn 2005–2015, rõ hơn khi thị trường giảm; Hoang và Luu (2024), trong một bản thảo công bố trực tuyến, phân tích chế độ biến động của VN-Index giai đoạn 2012–2023. Về danh mục, Ta và Vuong (2020) áp dụng mô hình Black-Litterman với quan điểm dự báo từ mô hình ARIMA, Nguyen và cộng sự (2020) dùng ma trận hiệp phương sai co rút trên 468 tuần giai đoạn 2011–2019, Goutte và cộng sự (2025) so sánh các phương pháp ra quyết định đa tiêu chí trên rổ VN100, và bài báo của chính thí sinh (Nguyễn & Nguyễn, 2026a) áp dụng mô hình Black-Litterman có chuyển chế độ giai đoạn 2019–2025. Các công trình này tập trung vào HOSE và chưa so sánh hai sàn.")
md(109,"Bốn khoảng trống cùng chỉ ra","Bốn khoảng trống cùng chỉ ra một điểm: vai trò của sàn giao dịch đối với chất lượng thị trường và khả năng đầu tư chưa được đo cho Việt Nam, trong khi đợt hợp nhất năm 2026 tạo điều kiện đo trực tiếp. Nhận định này dựa trên tìm kiếm trên SSRN, RePEc/IDEAS, ScienceDirect, Oxford Academic, Wiley, Springer, Taylor & Francis, MDPI và arXiv đến ngày 30/9/2026, chưa gồm Scopus, Web of Science và các tạp chí trong nước. Thí sinh mới đọc tóm tắt và thông tin thư mục của phần lớn các nguồn; việc đọc toàn văn và mở rộng tìm kiếm nằm trong kế hoạch năm thứ nhất.")
md(121,"Mỗi giả thuyết đi kèm","Mỗi giả thuyết đi kèm một khả năng đối lập. Với H1, điểm GFCI có thể chỉ phản ánh thu nhập và thể chế. Với H2, chênh lệch có thể do quy mô doanh nghiệp và do biên độ dao động giá khác nhau giữa các sàn, hiện là ±7% ở HOSE, ±10% ở HNX và ±15% ở UPCoM. Theo Điều 4 Thông tư số 120/2020/TT-BTC, biên độ do VNX quyết định sau khi Ủy ban Chứng khoán Nhà nước chấp thuận, và Ủy ban Chứng khoán Nhà nước có thể điều chỉnh biên độ khi cần ổn định thị trường (Bộ Tài chính, 2020) [CẦN XÁC MINH các lần thay đổi biên độ trong giai đoạn 2009–2025]. Vì vậy, chỉ số được so sánh trên mẫu đối sánh theo quy mô và ngành, và được tính lại sau khi bỏ hai chỉ báo bị biên độ cắt trực tiếp là độ phi thanh khoản Amihud và chênh lệch Corwin–Schultz.")
md(123,"Tỷ lệ ngày lợi suất bằng 0","Vì tỷ lệ ngày lợi suất bằng 0 và chênh lệch Corwin–Schultz phản ánh một phần bước giá, nhất là ở cổ phiếu giá thấp, hai chỉ báo này được báo cáo theo nhóm mức giá, và thay đổi của tỷ lệ ngày lợi suất bằng 0 trong H3 được đọc cùng với mức giảm bước giá khi chuyển sàn.")
md(125,"Đề tài vì vậy tính Amihud","Đề tài vì vậy tính Amihud, ở cả hai nhóm và hai giai đoạn, chỉ trên các ngày có lợi suất tuyệt đối dưới một ngưỡng chung và không liền sau một ngày vượt ngưỡng này. Ngưỡng thấp hơn mức lợi suất lớn nhất đạt được ở biên độ ±7%, tính sau khi giá trần được làm tròn xuống và giá sàn được làm tròn lên theo đơn vị yết giá của HOSE (Sở Giao dịch Chứng khoán Thành phố Hồ Chí Minh, 2025). Vì ngưỡng giống nhau cho mọi cổ phiếu và mọi giai đoạn, tập ngày bị loại không đổi theo sàn. Giá trị ngưỡng và số ngày hợp lệ tối thiểu mỗi tháng được ghi trong tệp đăng ký; tỷ lệ ngày bị loại được báo cáo theo nhóm và giai đoạn. Giá trị giao dịch chỉ gồm giao dịch khớp lệnh, và vòng quay, thước đo không dùng lợi suất, là thước đo đối chiếu.")
md(160,"Giữ nguyên thành phần rổ","Giữ nguyên thành phần rổ giúp so sánh cùng các cổ phiếu quanh sự kiện. Thông tin tại ngày tham chiếu có thể lỗi thời ở các cửa sổ xa, và mã được chọn vì thanh khoản cao có thể hồi quy về trung bình, nhưng hai rổ được lập theo cùng quy tắc nên các thiên lệch này tác động lên cả hai.")
md(170,"Phương trình (5) được ước lượng","Phương trình (5) được ước lượng trên giai đoạn tham chiếu (đến tháng 6/2025) và giai đoạn sau sự kiện (từ tháng 1/2027); các tháng từ 7/2025 đến 12/2026, gồm tháng chuyển sàn, chỉ được đưa vào phương trình (6). Vì giai đoạn tham chiếu dài 16 năm, cửa sổ trước của ước lượng chính bắt đầu sau điểm gãy cấu trúc cuối cùng của chuỗi chênh lệch theo tháng (Bai & Perron, 1998), và ước lượng với cửa sổ trước 24 tháng (7/2023–6/2025) được báo cáo kèm.")
md(176,"Việc chuyển sàn đổi ba quy tắc","Việc chuyển sàn đổi ba quy tắc cùng lúc, và mỗi quy tắc tác động mạnh yếu khác nhau tùy cổ phiếu. Biên độ hẹp lại chỉ ràng buộc những mã thường có lợi suất ngày lớn; bước giá nhỏ đi chủ yếu ở mã giá thấp; việc vào VN-Index và các chỉ số khác do HOSE xây dựng tạo áp lực cầu lớn hơn ở mã có vốn hóa lớn so với giá trị giao dịch [CẦN XÁC MINH cách HOSE xử lý mã chuyển sàn trong các chỉ số]. Ba mức chịu cú sốc tương ứng được đo bằng dữ liệu đến ngày 30/6/2025: tỷ lệ ngày có lợi suất tuyệt đối từ 7% đến dưới 10%; nghịch đảo của giá đóng cửa bình quân, báo cáo thêm với mức giảm bước giá nêu ở mục 4.3.2; và tỷ số giữa vốn hóa toàn phần và giá trị giao dịch bình quân ngày, vì VN-Index không điều chỉnh tỷ lệ tự do chuyển nhượng (Sở Giao dịch Chứng khoán Thành phố Hồ Chí Minh, 2026).")
de(177,"Ba mức chịu cú sốc tương ứng")
md(178,"Việc FTSE Russell đưa","Bộ quy tắc của FTSE Russell coi cả HOSE và HNX là sàn đủ điều kiện ở Việt Nam (FTSE Russell, 2026a), nên việc đổi sàn tự nó không thay đổi tư cách được sàng lọc của một mã, và việc FTSE Russell đưa cổ phiếu Việt Nam vào chỉ số không được coi là một kênh của việc chuyển sàn. Danh sách cổ phiếu đủ điều kiện, lập với dữ liệu đến ngày 30/6/2026, chỉ gồm mã niêm yết tại HOSE (FTSE Russell, 2026b) và được dùng để loại mã khỏi nhóm đối chứng HOSE. Nếu mã chuyển sàn nào được đưa vào chỉ số ở các kỳ xét duyệt sau ngày 28/12/2026, δ được ước lượng thêm khi loại các mã này.")
md(181,"Sai số chuẩn phân cụm theo cổ phiếu coi","Mỗi hệ số tương tác được suy luận như δ, vì sai số chuẩn phân cụm theo cổ phiếu coi các mã là độc lập và bác bỏ quá thường xuyên khi cú sốc chung theo tháng tác động mạnh hơn lên mã chịu cú sốc mạnh. Với từng tháng, đề tài lấy hệ số góc của logarit Amihud theo mức chịu cú sốc ở mã chuyển sàn trừ hệ số góc ở mã đối chứng, rồi áp dụng bootstrap tự hồi quy cho chuỗi hiệu số này, với mức ý nghĩa hai phía 5%. Các hệ số tương tác, kể cả tương tác theo trụ sở, là phân tích phụ đăng ký trước và không đưa vào thủ tục Holm.")
md(182,"Phân tích theo trụ sở kiểm tra","Phân tích theo trụ sở kiểm tra xem việc chuyển sàn có tác động khác nhau đến doanh nghiệp có trụ sở tại Hà Nội và doanh nghiệp ở nơi khác hay không. Văn liệu cho thấy nhà quản lý quỹ ưa nắm giữ cổ phiếu của doanh nghiệp có trụ sở gần mình (Coval & Moskowitz, 1999) và thanh khoản của cổ phiếu phụ thuộc vào vị trí trụ sở (Loughran & Schultz, 2005) [CẦN ĐỐI CHIẾU bản gốc của hai bài], nhưng hai bài này nói về khoảng cách giữa nhà đầu tư và doanh nghiệp, không nói về vị trí của sàn. Kênh mà đề tài kiểm tra là sự chú ý và thông tin gắn với nơi đặt sàn: nếu kênh này có thật, cổ phiếu của doanh nghiệp có trụ sở tại Hà Nội được lợi ít hơn khi chuyển sang HOSE.")
md(189,"Sai số chuẩn được phân cụm theo quốc gia","Sai số chuẩn được phân cụm theo quốc gia. Vì *SMD* thay đổi chậm, *β* chủ yếu được xác định từ biến thiên theo thời gian trong từng quốc gia; ước lượng không có hiệu ứng cố định theo trung tâm được báo cáo thêm. Điểm GFCI gộp kết quả khảo sát với các nhân tố định lượng, trong đó vốn hóa, giá trị và khối lượng giao dịch cổ phiếu lấy từ Liên đoàn các Sở Giao dịch Thế giới (3 trong 144 nhân tố của kỳ GFCI 40; Wardle & Mainelli, 2026). Vì phần trùng lặp cơ học này, và vì trung tâm mạnh có thể kéo theo giao dịch cổ phiếu, *β* được gọi là liên hệ có điều kiện. H1 được ủng hộ khi *β* dương với giá trị p nhỏ hơn ngưỡng Holm tương ứng.")
md(195,"Nếu nhóm đối chứng HOSE mất","Nếu nhóm đối chứng HOSE mất thanh khoản do dòng lệnh chuyển sang cổ phiếu chuyển sàn, δ phóng đại tác động, và ước lượng với nhóm đối chứng UPCoM, nếu nhóm này còn dữ liệu sau sự kiện, là một cận khác. Ngược lại, nếu thanh khoản lan tỏa dương sang nhóm đối chứng HOSE, như đã ghi nhận ở Tel Aviv (Amihud và cộng sự, 1997) và quanh đợt hợp nhất Tokyo–Osaka (Hisada, 2018), δ đánh giá thấp tác động.")
md(197,"Từ bằng chứng đến định hướng","**Từ bằng chứng đến định hướng cho Hà Nội.** Kết quả H1–H4 được tổng hợp cùng phép so sánh vai trò của Hà Nội với Bắc Kinh và Thượng Hải (Lai, 2012; Wang và cộng sự, 2007) và với Thành phố Hồ Chí Minh, dựa trên văn bản chính sách và dữ liệu công khai, thành định hướng chuyên môn hóa cho các thị trường mà HNX tiếp tục vận hành. Ngoài phân tích theo trụ sở ở mục 4.3.7, phần này là tổng hợp định tính, không kiểm định giả thuyết. Nếu người hướng dẫn và các tổ chức liên quan đồng ý, thí sinh lấy ý kiến chuyên gia không chính thức.")
md(207,"Chẳng hạn, với σ","Chẳng hạn, với σ = 0,2 và φ = 0,6, đề tài chỉ phát hiện được mức giảm logarit Amihud từ khoảng 0,25 trở lên, tương đương độ phi thanh khoản giảm khoảng 22%. Đây là giả định minh họa: thí sinh sẽ ước lượng σ và φ từ giai đoạn tham chiếu, tính lại hiệu ứng nhỏ nhất phát hiện được bằng mô phỏng theo đúng thủ tục kiểm định của H3, và ghi kết quả vào tệp đăng ký trước ngày 28/12/2026.")
